<?php require 'includes/layout.php';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$s=db()->prepare('SELECT id FROM users WHERE email=?');$s->execute([trim($_POST['email']??'')]);$u=$s->fetch();if($u){$token=bin2hex(random_bytes(32));$hash=hash('sha256',$token);db()->prepare('DELETE FROM password_resets WHERE user_id=?')->execute([$u['id']]);db()->prepare('INSERT INTO password_resets(user_id,token_hash,expires_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 30 MINUTE))')->execute([$u['id'],$hash]);$devLink='reset-password.php?token='.urlencode($token);} $sent=true;}top('Forgot Password'); ?><div class="panel"><p>Enter your email to request a password reset.</p><?php if(isset($sent)):?><div class="notice">If the account exists, a reset link has been generated.</div><?php if(isset($devLink)):?><p class="error">LOCAL DEMO ONLY — reset link (in production, email this instead):</p><p><a href="<?=e($devLink)?>">Open password reset</a></p><?php endif;?><?php endif;?><form class="form" method="post"><?php csrf_field();?><label>Email<input type="email" name="email" required></label><button class="btn">Request reset</button></form></div><?php bottom(); ?>